import json, random, sys, time
sys.path.insert(0,'/workspace/tmp')
from harness import run

def case(seed, nf=22, nn=64, pstyle='cover', capset=(1,2,3), H=64):
    rng = random.Random(seed)
    nodes = ['n%02d'%i for i in range(nn)]
    flows=[]
    for i in range(nf):
        if pstyle=='cover':
            path = rng.sample(nodes, min(nn, 9))
        elif pstyle=='half':
            path = rng.sample(nodes[:nn//2], min(nn//2,9))
        else:
            path = rng.sample(nodes, rng.randint(2,9))
        kinds=['K']*(H-6)+['D']*4+['Z','Q','T']
        flows.append({'id':'f%02d'%i,'path':path,'template':bytes(rng.randrange(256) for _ in range(H)).hex(),'kinds':''.join(kinds)})
    caps={n: rng.choice(capset) for n in nodes}
    offers={}
    for f in flows:
        hb=bytearray(H)
        for pos,c in enumerate(f['kinds']):
            if c=='K': hb[pos]=int(f['template'][2*pos:2*pos+2],16)
            elif c=='Q': hb[pos]=3
            elif c=='T': hb[pos]=250
        offers[f['id']]=[{'header':bytes(hb).hex(),'count':10**9}]
    return {'mode':'plan','capacities':caps,'flows':flows,'warmup':0,'pinned':[],'offers':offers}

tests=[]
for seed in range(5):
    tests.append(('cover-tight', case(seed, pstyle='cover', capset=(1,2,3))))
    tests.append(('cover-loose', case(seed, pstyle='cover', capset=(6,7,8))))
    tests.append(('half', case(seed, pstyle='half', capset=(2,3))))
    tests.append(('rand', case(seed, pstyle='rand', capset=(1,2))))
# equal benefits adversarial
c = case(99, pstyle='cover', capset=(5,5))
c['offers'] = {f['id']: [{'header': h['header'], 'count': 1000+i} for i,h in enumerate(c['offers'][f['id']])] for f in c['flows']}
tests.append(('equalish', c))
for name, req in tests:
    t=time.time(); out=run([req]); dt=time.time()-t
    print('%-14s %6.2fs saved=%d nsel=%d' % (name, dt, out[0].get('saved',-1), len(out[0].get('selected',[]))))
